INSERT INTO ropa.activity_templates (template_set_id, code, name_th, name_en, job_category, role, defaults, rationale, legal_refs) VALUES
        ('00000000-0000-7000-8000-000000000001', 'recruitment_job_posting', 'ประกาศรับสมัครงานและคัดกรองใบสมัคร', 'Job posting and application screening', 'recruitment', 'controller', '{"description_th": "เผยแพร่ตำแหน่งงานว่างและคัดกรองคุณสมบัติผู้สมัครเบื้องต้น", "description_en": "Publish openings and screen applicant qualifications", "purposes": [{"purpose_text_th": "สรรหาและคัดเลือกบุคลากร", "purpose_text_en": "Recruit and select personnel", "lawful_basis_code": "CONTRACT"}], "data": [{"data_category_code": "identity", "subject_type_code": "job_applicant", "source": "direct"}, {"data_category_code": "contact", "subject_type_code": "job_applicant", "source": "direct"}, {"data_category_code": "education", "subject_type_code": "job_applicant", "source": "direct"}, {"data_category_code": "employment", "subject_type_code": "job_applicant", "source": "direct"}], "recipients": [{"recipient_role": "processor", "note_th": "ผู้ให้บริการระบบสรรหาบุคลากร (ATS) ภายนอก"}], "retention": [{"retention_months": 12, "retention_basis_th": "เก็บไว้พิจารณาตำแหน่งอื่นที่เหมาะสมภายในระยะเวลาที่แจ้งผู้สมัคร", "trigger_event_th": "วันที่ปิดรับสมัครหรือสิ้นสุดกระบวนการ", "disposal_method": "delete"}], "security_controls": ["AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับลักษณะความสัมพันธ์และวัตถุประสงค์ของกิจกรรม \"ประกาศรับสมัครงานและคัดกรองใบสมัคร\" ตามมาตรา 24/26", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของกิจกรรมประเภทนี้ โปรดปรับตามนโยบายและข้อกำหนดกฎหมายเฉพาะของแต่ละองค์กร", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงทั่วไป ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)']),
        ('00000000-0000-7000-8000-000000000001', 'recruitment_interview', 'นัดหมายและสัมภาษณ์ผู้สมัครงาน', 'Interview scheduling and evaluation', 'recruitment', 'controller', '{"description_th": "จัดตารางสัมภาษณ์และบันทึกผลการประเมินผู้สมัคร", "description_en": "Schedule interviews and record evaluation results", "purposes": [{"purpose_text_th": "ประเมินความเหมาะสมของผู้สมัครก่อนเข้าทำสัญญาจ้าง", "purpose_text_en": "Assess applicant fit before employment contract", "lawful_basis_code": "CONTRACT"}], "data": [{"data_category_code": "identity", "subject_type_code": "job_applicant", "source": "direct"}, {"data_category_code": "contact", "subject_type_code": "job_applicant", "source": "direct"}, {"data_category_code": "employment", "subject_type_code": "job_applicant", "source": "direct"}], "recipients": [], "retention": [{"retention_months": 6, "retention_basis_th": "เก็บผลสัมภาษณ์เพื่อประกอบการตัดสินใจและตอบข้อโต้แย้งที่อาจเกิดขึ้น", "trigger_event_th": "วันที่ประกาศผลการคัดเลือก", "disposal_method": "delete"}], "security_controls": ["AC_ROLE_BASED"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับลักษณะความสัมพันธ์และวัตถุประสงค์ของกิจกรรม \"นัดหมายและสัมภาษณ์ผู้สมัครงาน\" ตามมาตรา 24/26", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของกิจกรรมประเภทนี้ โปรดปรับตามนโยบายและข้อกำหนดกฎหมายเฉพาะของแต่ละองค์กร", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงทั่วไป ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)']),
        ('00000000-0000-7000-8000-000000000001', 'recruitment_background_check', 'ตรวจสอบประวัติผู้สมัครก่อนจ้างงาน', 'Pre-employment background check', 'recruitment', 'controller', '{"description_th": "ตรวจสอบประวัติการทำงาน การศึกษา และคดีอาญาของผู้สมัครที่ผ่านการคัดเลือกรอบสุดท้าย", "description_en": "Verify work history, education and criminal record of finalist candidates", "purposes": [{"purpose_text_th": "ตรวจสอบคุณสมบัติและความเหมาะสมก่อนเข้าทำสัญญาจ้าง", "purpose_text_en": "Verify qualifications before employment", "lawful_basis_code": "CONTRACT"}, {"purpose_text_th": "ตรวจสอบประวัติอาชญากรรมเท่าที่กฎหมายหรือตำแหน่งงานกำหนด", "purpose_text_en": "Check criminal record where legally required", "lawful_basis_code": "S26_LAW"}], "data": [{"data_category_code": "identity", "subject_type_code": "job_applicant", "source": "indirect"}, {"data_category_code": "employment", "subject_type_code": "job_applicant", "source": "indirect"}, {"data_category_code": "education", "subject_type_code": "job_applicant", "source": "indirect"}, {"data_category_code": "criminal_record", "subject_type_code": "job_applicant", "source": "indirect"}], "recipients": [{"recipient_role": "processor", "note_th": "ผู้ให้บริการตรวจสอบประวัติภายนอก"}], "retention": [{"retention_months": 3, "retention_basis_th": "เก็บผลตรวจสอบเพื่อประกอบการตัดสินใจจ้างงาน", "trigger_event_th": "วันที่เริ่มงานหรือยุติกระบวนการสรรหา", "disposal_method": "delete"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED", "PHYS_DOC_DISPOSAL"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับลักษณะความสัมพันธ์และวัตถุประสงค์ของกิจกรรม \"ตรวจสอบประวัติผู้สมัครก่อนจ้างงาน\" ตามมาตรา 24/26", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของกิจกรรมประเภทนี้ โปรดปรับตามนโยบายและข้อกำหนดกฎหมายเฉพาะของแต่ละองค์กร", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงทั่วไป ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(2)','ม.39(4)']),
        ('00000000-0000-7000-8000-000000000001', 'recruitment_onboarding', 'จัดทำสัญญาจ้างและเริ่มงานพนักงานใหม่', 'New hire contracting and onboarding', 'recruitment', 'controller', '{"description_th": "จัดเตรียมสัญญาจ้างและเอกสารประกอบการเริ่มงานของพนักงานใหม่", "description_en": "Prepare employment contract and onboarding documents", "purposes": [{"purpose_text_th": "จัดทำและบริหารสัญญาจ้างแรงงาน", "purpose_text_en": "Create and manage the employment contract", "lawful_basis_code": "CONTRACT"}], "data": [{"data_category_code": "identity", "subject_type_code": "employee", "source": "direct"}, {"data_category_code": "contact", "subject_type_code": "employee", "source": "direct"}, {"data_category_code": "national_id", "subject_type_code": "employee", "source": "direct"}, {"data_category_code": "financial", "subject_type_code": "employee", "source": "direct"}], "recipients": [{"recipient_role": "government", "note_th": "หน่วยงานประกันสังคมและกรมสรรพากรตามที่กฎหมายกำหนด"}], "retention": [{"retention_months": 120, "retention_basis_th": "เก็บตามอายุความฟ้องร้องคดีแรงงานและข้อกำหนดด้านภาษี", "trigger_event_th": "วันที่พ้นสภาพการเป็นพนักงาน", "disposal_method": "anonymize"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED", "PHYS_SITE_ACCESS"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับลักษณะความสัมพันธ์และวัตถุประสงค์ของกิจกรรม \"จัดทำสัญญาจ้างและเริ่มงานพนักงานใหม่\" ตามมาตรา 24/26", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของกิจกรรมประเภทนี้ โปรดปรับตามนโยบายและข้อกำหนดกฎหมายเฉพาะของแต่ละองค์กร", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงทั่วไป ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)','ม.39(5)']),
        ('00000000-0000-7000-8000-000000000001', 'payroll_processing', 'ประมวลผลเงินเดือนและค่าจ้าง', 'Payroll processing', 'payroll', 'controller', '{"description_th": "คำนวณและจ่ายเงินเดือน ค่าล่วงเวลา และหักภาษี ณ ที่จ่าย", "description_en": "Calculate and pay salary, overtime and withholding tax", "purposes": [{"purpose_text_th": "ปฏิบัติตามสัญญาจ้างแรงงานในการจ่ายค่าตอบแทน", "purpose_text_en": "Pay compensation under the employment contract", "lawful_basis_code": "CONTRACT"}, {"purpose_text_th": "ปฏิบัติตามกฎหมายภาษีและประกันสังคม", "purpose_text_en": "Comply with tax and social-security law", "lawful_basis_code": "LEGAL_OBLIGATION"}], "data": [{"data_category_code": "identity", "subject_type_code": "employee", "source": "direct"}, {"data_category_code": "financial", "subject_type_code": "employee", "source": "direct"}, {"data_category_code": "national_id", "subject_type_code": "employee", "source": "direct"}], "recipients": [{"recipient_role": "processor", "note_th": "ผู้ให้บริการระบบเงินเดือนภายนอก (ถ้ามี)"}, {"recipient_role": "government", "note_th": "กรมสรรพากรและสำนักงานประกันสังคม"}], "retention": [{"retention_months": 120, "retention_basis_th": "เก็บตามข้อกำหนดบัญชีและภาษีอากร", "trigger_event_th": "วันสิ้นปีบัญชีที่เกี่ยวข้อง", "disposal_method": "anonymize"}], "security_controls": ["TECH_ENCRYPTION", "AC_ROLE_BASED", "TECH_ACCESS_LOG"]}'::jsonb, '{"purpose_th": "ฐานทางกฎหมายที่เลือกสอดคล้องกับลักษณะความสัมพันธ์และวัตถุประสงค์ของกิจกรรม \"ประมวลผลเงินเดือนและค่าจ้าง\" ตามมาตรา 24/26", "retention_th": "ระยะเวลาเก็บรักษาอ้างอิงแนวปฏิบัติทั่วไปของกิจกรรมประเภทนี้ โปรดปรับตามนโยบายและข้อกำหนดกฎหมายเฉพาะของแต่ละองค์กร", "security_th": "มาตรการความปลอดภัยที่แนะนำครอบคลุมตามประเภทข้อมูลที่ประมวลผลในกิจกรรมนี้ ตามประกาศมาตรการความปลอดภัย พ.ศ. 2565", "note_th": "ค่าตั้งต้นนี้เป็นร่างอ้างอิงทั่วไป ยังไม่ได้รับการตรวจสอบจากฝ่ายกฎหมาย โปรดทบทวนก่อนใช้งานจริง"}'::jsonb, ARRAY['ม.39(1)','ม.39(4)','ม.39(5)']),
